function getDefaultElementalSkillS(element) {
  const map = {
    fire: "fire_s",
    water: "water_s",
    wind: "wind_s",
    earth: "earth_s",
    lightning: "lightning_s",
    ice: "ice_s",
    plant: "plant_s",
    poison: "poison_s",
    dark: "dark_s",
    light: "light_s",
    psychic: "psychic_s"
  };
  return map[element] || "fire_s";
}
