      if (!saveManager.consumeResources({ crystals: skill.unlockCost.crystals })) {
        return { success: false, error: "\u0E04\u0E23\u0E34\u0E2A\u0E15\u0E31\u0E25\u0E44\u0E21\u0E48\u0E1E\u0E2D" };
      }
