  "\u0E15\u0E31\u0E27\u0E19\u0E34\u0E48\u0E21": { cat: "\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E40\u0E25\u0E35\u0E49\u0E22\u0E07\u0E25\u0E39\u0E01\u0E14\u0E49\u0E27\u0E22\u0E19\u0E21\u0E40\u0E01\u0E25\u0E47\u0E14\u0E40\u0E04\u0E23\u0E32\u0E15\u0E34\u0E19 (Pholidota)", diet: "\u0E01\u0E34\u0E19\u0E21\u0E14\u0E41\u0E25\u0E30\u0E1B\u0E25\u0E27\u0E01 (Insectivore)", habitat: "\u0E1B\u0E48\u0E32\u0E40\u0E02\u0E15\u0E23\u0E49\u0E2D\u0E19\u0E41\u0E25\u0E30\u0E17\u0E38\u0E48\u0E07\u0E2B\u0E0D\u0E49\u0E32" },
  "\u0E40\u0E21\u0E48\u0E19": { cat: "\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E40\u0E25\u0E35\u0E49\u0E22\u0E07\u0E25\u0E39\u0E01\u0E14\u0E49\u0E27\u0E22\u0E19\u0E21\u0E02\u0E19\u0E2B\u0E19\u0E32\u0E21 (Hystricidae)", diet: "\u0E01\u0E34\u0E19\u0E1E\u0E37\u0E0A\u0E41\u0E25\u0E30\u0E23\u0E32\u0E01\u0E44\u0E21\u0E49 (Herbivore)", habitat: "\u0E1B\u0E48\u0E32\u0E42\u0E1B\u0E23\u0E48\u0E07\u0E41\u0E25\u0E30\u0E42\u0E02\u0E14\u0E2B\u0E34\u0E19\u0E1C\u0E32" },
  // สัตว์น้ำและสัตว์ครึ่งบกครึ่งน้ำ
  "\u0E1B\u0E25\u0E32": { cat: "\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E21\u0E35\u0E01\u0E23\u0E30\u0E14\u0E39\u0E01\u0E2A\u0E31\u0E19\u0E2B\u0E25\u0E31\u0E07\u0E43\u0E19\u0E19\u0E49\u0E33 (Pisces)", diet: "\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E19\u0E49\u0E33\u0E01\u0E34\u0E19\u0E40\u0E19\u0E37\u0E49\u0E2D/\u0E1E\u0E37\u0E0A", habitat: "\u0E41\u0E21\u0E48\u0E19\u0E49\u0E33 \u0E17\u0E30\u0E40\u0E25\u0E2A\u0E32\u0E1A \u0E41\u0E25\u0E30\u0E21\u0E2B\u0E32\u0E2A\u0E21\u0E38\u0E17\u0E23" },
  "\u0E09\u0E25\u0E32\u0E21": { cat: "\u0E1B\u0E25\u0E32\u0E01\u0E23\u0E30\u0E14\u0E39\u0E01\u0E2D\u0E48\u0E2D\u0E19\u0E19\u0E31\u0E01\u0E25\u0E48\u0E32\u0E41\u0E2B\u0E48\u0E07\u0E17\u0E49\u0E2D\u0E07\u0E17\u0E30\u0E40\u0E25 (Chondrichthyes)", diet: "\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E01\u0E34\u0E19\u0E40\u0E19\u0E37\u0E49\u0E2D\u0E41\u0E17\u0E49 (Apex Predator)", habitat: "\u0E21\u0E2B\u0E32\u0E2A\u0E21\u0E38\u0E17\u0E23\u0E40\u0E1B\u0E34\u0E14\u0E41\u0E25\u0E30\u0E41\u0E19\u0E27\u0E1B\u0E30\u0E01\u0E32\u0E23\u0E31\u0E07" },
  "\u0E27\u0E32\u0E2C": { cat: "\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E40\u0E25\u0E35\u0E49\u0E22\u0E07\u0E25\u0E39\u0E01\u0E14\u0E49\u0E27\u0E22\u0E19\u0E21\u0E43\u0E19\u0E19\u0E49\u0E33\u0E02\u0E19\u0E32\u0E14\u0E22\u0E31\u0E01\u0E29\u0E4C (Cetacea)", diet: "\u0E01\u0E34\u0E19\u0E41\u0E1E\u0E25\u0E07\u0E01\u0E4C\u0E15\u0E2D\u0E19 \u0E40\u0E04\u0E22 \u0E41\u0E25\u0E30\u0E1B\u0E25\u0E32\u0E40\u0E25\u0E47\u0E01", habitat: "\u0E21\u0E2B\u0E32\u0E2A\u0E21\u0E38\u0E17\u0E23\u0E25\u0E36\u0E01\u0E17\u0E31\u0E48\u0E27\u0E42\u0E25\u0E01" },
  "\u0E42\u0E25\u0E21\u0E32": { cat: "\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E40\u0E25\u0E35\u0E49\u0E22\u0E07\u0E25\u0E39\u0E01\u0E14\u0E49\u0E27\u0E22\u0E19\u0E21\u0E17\u0E23\u0E07\u0E1B\u0E31\u0E0D\u0E0D\u0E32\u0E43\u0E19\u0E19\u0E49\u0E33 (Delphinidae)", diet: "\u0E01\u0E34\u0E19\u0E1B\u0E25\u0E32\u0E41\u0E25\u0E30\u0E2B\u0E21\u0E36\u0E01 (Carnivore)", habitat: "\u0E19\u0E48\u0E32\u0E19\u0E19\u0E49\u0E33\u0E0A\u0E32\u0E22\u0E1D\u0E31\u0E48\u0E07\u0E41\u0E25\u0E30\u0E17\u0E30\u0E40\u0E25\u0E40\u0E1B\u0E34\u0E14" },
  "\u0E2B\u0E21\u0E36\u0E01": { cat: "\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E44\u0E21\u0E48\u0E21\u0E35\u0E01\u0E23\u0E30\u0E14\u0E39\u0E01\u0E2A\u0E31\u0E19\u0E2B\u0E25\u0E31\u0E07\u0E21\u0E2D\u0E25\u0E25\u0E31\u0E2A\u0E01\u0E32 (Cephalopoda)", diet: "\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E01\u0E34\u0E19\u0E40\u0E19\u0E37\u0E49\u0E2D (Carnivore)", habitat: "\u0E41\u0E19\u0E27\u0E1B\u0E30\u0E01\u0E32\u0E23\u0E31\u0E07\u0E41\u0E25\u0E30\u0E43\u0E15\u0E49\u0E17\u0E30\u0E40\u0E25\u0E25\u0E36\u0E01" },
  "\u0E01\u0E1A": { cat: "\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E2A\u0E30\u0E40\u0E17\u0E34\u0E19\u0E19\u0E49\u0E33\u0E2A\u0E30\u0E40\u0E17\u0E34\u0E19\u0E1A\u0E01 (Amphibia)", diet: "\u0E01\u0E34\u0E19\u0E41\u0E21\u0E25\u0E07\u0E41\u0E25\u0E30\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E02\u0E19\u0E32\u0E14\u0E40\u0E25\u0E47\u0E01", habitat: "\u0E2B\u0E19\u0E2D\u0E07\u0E19\u0E49\u0E33 \u0E23\u0E34\u0E21\u0E18\u0E32\u0E23 \u0E41\u0E25\u0E30\u0E1B\u0E48\u0E32\u0E0A\u0E37\u0E49\u0E19" },
  "\u0E04\u0E32\u0E07\u0E04\u0E01": { cat: "\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E2A\u0E30\u0E40\u0E17\u0E34\u0E19\u0E19\u0E49\u0E33\u0E2A\u0E30\u0E40\u0E17\u0E34\u0E19\u0E1A\u0E01\u0E1C\u0E34\u0E27\u0E02\u0E23\u0E38\u0E02\u0E23\u0E30 (Bufonidae)", diet: "\u0E01\u0E34\u0E19\u0E41\u0E21\u0E25\u0E07\u0E41\u0E25\u0E30\u0E2B\u0E19\u0E2D\u0E19 (Insectivore)", habitat: "\u0E1B\u0E48\u0E32\u0E42\u0E1B\u0E23\u0E48\u0E07 \u0E2A\u0E27\u0E19 \u0E41\u0E25\u0E30\u0E43\u0E15\u0E49\u0E02\u0E2D\u0E19\u0E44\u0E21\u0E49" },
  "\u0E40\u0E15\u0E48\u0E32": { cat: "\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E40\u0E25\u0E37\u0E49\u0E2D\u0E22\u0E04\u0E25\u0E32\u0E19\u0E01\u0E23\u0E30\u0E14\u0E2D\u0E07\u0E41\u0E02\u0E47\u0E07 (Testudines)", diet: "\u0E01\u0E34\u0E19\u0E17\u0E31\u0E49\u0E07\u0E1E\u0E37\u0E0A\u0E41\u0E25\u0E30\u0E2A\u0E31\u0E15\u0E27\u0E4C (Omnivore)", habitat: "\u0E41\u0E21\u0E48\u0E19\u0E49\u0E33 \u0E17\u0E30\u0E40\u0E25\u0E2A\u0E32\u0E1A \u0E41\u0E25\u0E30\u0E21\u0E2B\u0E32\u0E2A\u0E21\u0E38\u0E17\u0E23" },
  "\u0E08\u0E23\u0E30\u0E40\u0E02\u0E49": { cat: "\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E40\u0E25\u0E37\u0E49\u0E2D\u0E22\u0E04\u0E25\u0E32\u0E19\u0E42\u0E1A\u0E23\u0E32\u0E13\u0E23\u0E34\u0E21\u0E19\u0E49\u0E33 (Crocodylidae)", diet: "\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E01\u0E34\u0E19\u0E40\u0E19\u0E37\u0E49\u0E2D (Apex Carnivore)", habitat: "\u0E41\u0E21\u0E48\u0E19\u0E49\u0E33 \u0E2B\u0E19\u0E2D\u0E07\u0E19\u0E49\u0E33 \u0E41\u0E25\u0E30\u0E1B\u0E32\u0E01\u0E2D\u0E48\u0E32\u0E27" },
  "\u0E1B\u0E39": { cat: "\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E02\u0E32\u0E1B\u0E25\u0E49\u0E2D\u0E07\u0E40\u0E1B\u0E25\u0E37\u0E2D\u0E01\u0E2B\u0E19\u0E32 (Brachyura)", diet: "\u0E01\u0E34\u0E19\u0E17\u0E31\u0E49\u0E07\u0E1E\u0E37\u0E0A\u0E41\u0E25\u0E30\u0E2A\u0E31\u0E15\u0E27\u0E4C (Omnivore)", habitat: "\u0E0A\u0E32\u0E22\u0E2B\u0E32\u0E14 \u0E1B\u0E48\u0E32\u0E0A\u0E32\u0E22\u0E40\u0E25\u0E19 \u0E41\u0E25\u0E30\u0E01\u0E49\u0E19\u0E17\u0E30\u0E40\u0E25" },
  "\u0E2B\u0E2D\u0E22": { cat: "\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E44\u0E21\u0E48\u0E21\u0E35\u0E01\u0E23\u0E30\u0E14\u0E39\u0E01\u0E2A\u0E31\u0E19\u0E2B\u0E25\u0E31\u0E07\u0E01\u0E32\u0E1A/\u0E40\u0E01\u0E25\u0E35\u0E22\u0E27 (Mollusca)", diet: "\u0E01\u0E23\u0E2D\u0E07\u0E01\u0E34\u0E19\u0E08\u0E38\u0E25\u0E34\u0E19\u0E17\u0E23\u0E35\u0E22\u0E4C\u0E41\u0E25\u0E30\u0E40\u0E28\u0E29\u0E1E\u0E37\u0E0A", habitat: "\u0E14\u0E34\u0E19\u0E40\u0E25\u0E19 \u0E01\u0E49\u0E19\u0E41\u0E21\u0E48\u0E19\u0E49\u0E33 \u0E41\u0E25\u0E30\u0E43\u0E15\u0E49\u0E0B\u0E32\u0E01\u0E43\u0E1A\u0E44\u0E21\u0E49" },
  // แมลงและสัตว์ขาปล้อง
  "\u0E1C\u0E36\u0E49\u0E07": { cat: "\u0E41\u0E21\u0E25\u0E07\u0E2A\u0E31\u0E07\u0E04\u0E21\u0E1C\u0E2A\u0E21\u0E40\u0E01\u0E2A\u0E23 (Apidae)", diet: "\u0E19\u0E49\u0E33\u0E2B\u0E27\u0E32\u0E19\u0E41\u0E25\u0E30\u0E40\u0E01\u0E2A\u0E23\u0E14\u0E2D\u0E01\u0E44\u0E21\u0E49 (Nectarivore)", habitat: "\u0E23\u0E31\u0E07\u0E1C\u0E36\u0E49\u0E07\u0E43\u0E19\u0E42\u0E1E\u0E23\u0E07\u0E44\u0E21\u0E49\u0E41\u0E25\u0E30\u0E17\u0E38\u0E48\u0E07\u0E14\u0E2D\u0E01\u0E44\u0E21\u0E49" },
  "\u0E15\u0E48\u0E2D": { cat: "\u0E41\u0E21\u0E25\u0E07\u0E19\u0E31\u0E01\u0E25\u0E48\u0E32\u0E40\u0E2B\u0E25\u0E47\u0E01\u0E43\u0E19\u0E1E\u0E34\u0E29 (Vespidae)", diet: "\u0E01\u0E34\u0E19\u0E41\u0E21\u0E25\u0E07\u0E41\u0E25\u0E30\u0E40\u0E19\u0E37\u0E49\u0E2D\u0E2A\u0E31\u0E15\u0E27\u0E4C\u0E02\u0E19\u0E32\u0E14\u0E40\u0E25\u0E47\u0E01", habitat: "\u0E23\u0E31\u0E07\u0E14\u0E34\u0E19\u0E2B\u0E23\u0E37\u0E2D\u0E23\u0E31\u0E07\u0E44\u0E21\u0E49\u0E15\u0E32\u0E21\u0E01\u0E34\u0E48\u0E07\u0E44\u0E21\u0E49\u0E2A\u0E39\u0E07" },
  "\u0E21\u0E14": { cat: "\u0E41\u0E21\u0E25\u0E07\u0E2A\u0E31\u0E07\u0E04\u0E21\u0E08\u0E2D\u0E21\u0E1E\u0E25\u0E31\u0E07 (Formicidae)", diet: "\u0E01\u0E34\u0E19\u0E17\u0E31\u0E49\u0E07\u0E1E\u0E37\u0E0A\u0E41\u0E25\u0E30\u0E2A\u0E31\u0E15\u0E27\u0E4C (Omnivore)", habitat: "\u0E23\u0E31\u0E07\u0E43\u0E15\u0E49\u0E14\u0E34\u0E19 \u0E42\u0E1E\u0E23\u0E07\u0E44\u0E21\u0E49 \u0E41\u0E25\u0E30\u0E0B\u0E32\u0E01\u0E1E\u0E37\u0E0A" },
